{
  "task_summary": "Predict whether a person's annual income exceeds the ACS income threshold used in Folktables ACSIncome, using person-level demographic and work-related attributes.",
  "scores": [
    {
      "feature_id": 0,
      "score": 0.72,
      "rationale": "Age is broadly and stably related to earnings through labor-market experience and lifecycle effects, though nonlinear and somewhat state-varying."
    },
    {
      "feature_id": 1,
      "score": 0.58,
      "rationale": "Class of worker is meaningfully tied to income differences across private, public, and self-employment sectors, but some categories reflect state-specific labor composition."
    },
    {
      "feature_id": 2,
      "score": 0.94,
      "rationale": "Educational attainment is one of the most robust and portable predictors of income across states because human-capital returns are broadly consistent."
    },
    {
      "feature_id": 3,
      "score": 0.41,
      "rationale": "Marital status correlates with household formation and labor-market attachment, but it is partly a demographic proxy and less directly causal for personal income."
    },
    {
      "feature_id": 4,
      "score": 0.83,
      "rationale": "Occupation strongly predicts earnings in a way that should generalize reasonably well, though detailed codes can pick up state-specific industry mix and sparse-category artifacts."
    },
    {
      "feature_id": 5,
      "score": 0.16,
      "rationale": "Place of birth may correlate with immigration and language-related labor outcomes, but it is also a demographic/geographic proxy with substantial risk of brittle state-specific shortcutting."
    },
    {
      "feature_id": 6,
      "score": 0.37,
      "rationale": "Relationship to householder can indicate life stage and household role associated with earnings, but it is indirect and entangled with household structure rather than stable individual productivity."
    },
    {
      "feature_id": 7,
      "score": 0.89,
      "rationale": "Usual hours worked is a strong, direct signal for annual income and should remain predictive across states despite some variation in part-time work prevalence."
    },
    {
      "feature_id": 8,
      "score": 0.12,
      "rationale": "Sex has predictive power due to persistent labor-market disparities, but it is a sensitive demographic shortcut that is less desirable for stable, semantics-based generalization."
    },
    {
      "feature_id": 9,
      "score": 0.08,
      "rationale": "Race can correlate with income through structural inequities, but it is a sensitive proxy with high risk of encoding non-portable demographic shortcuts rather than stable task semantics."
    }
  ]
}

